# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">METİN İÇİ VE METİNLER ARASI KARŞILAŞTIRMA (T.O.6.10 / T.O.6.11)</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Metin İçi Karşılaştırma</text>\n  <text x="180" y="108" text-anchor="middle" font-size="11" fill="#1e3a8a">• Aynı metnin farklı bölümleri, dörtlükleri</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11" fill="#1e3a8a">veya kahramanların değişen duyguları kıyaslanır.</text>\n  <text x="180" y="150" text-anchor="middle" font-size="11" fill="#334155">• Örnek: «Vatan» şiirinin ilk bölümünde</text>\n  <text x="180" y="166" text-anchor="middle" font-size="11" fill="#334155">vatanın doğal güzellikleri betimlenirken,</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#334155">son bölümünde şehitlerin fedakârlığı ve</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">bağımsızlık coşkusu öne çıkar.</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Metinler Arası Karşılaştırma</text>\n  <text x="520" y="108" text-anchor="middle" font-size="11" fill="#14532d">• İki farklı metin; tema, konu, ana fikir,</text>\n  <text x="520" y="124" text-anchor="middle" font-size="11" fill="#14532d">metin türü, anlatıcı ve dil yönünden kıyaslanır.</text>\n  <text x="520" y="150" text-anchor="middle" font-size="11" fill="#334155">• Örnek: Vatan konulu bir «şiir» (coşkulu,</text>\n  <text x="520" y="166" text-anchor="middle" font-size="11" fill="#334155">dizeli, imgeli) ile Millî Mücadele konulu bir</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" fill="#334155">«anı/hikâye» (olay örgülü, düzyazı)</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">ortak vatanseverlik temasında buluşur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSİM ÇEKİM EKLERİ (ÇOKLUK, HÂL, İYELİK VE SORU EKLERİ)</text>\n  <rect x="20" y="55" width="152" height="180" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="96" y="78" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">1. Çokluk Eki (-lar/-ler)</text>\n  <text x="96" y="104" text-anchor="middle" font-size="11" fill="#713f12">• Çoğul: Dağ-lar, kuş-lar</text>\n  <text x="96" y="126" text-anchor="middle" font-size="11" fill="#713f12">• Aile: Teyzem-ler</text>\n  <text x="96" y="148" text-anchor="middle" font-size="11" fill="#713f12">• Abartma: Dünya-lar</text>\n  <text x="96" y="170" text-anchor="middle" font-size="11" fill="#713f12">• Saygı: Müdür Bey-ler</text>\n  <text x="96" y="192" text-anchor="middle" font-size="11" fill="#713f12">• Benzerlik: Yunus-lar</text>\n  <rect x="186" y="55" width="152" height="180" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="262" y="78" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">2. Hâl (Durum) Ekleri</text>\n  <text x="262" y="104" text-anchor="middle" font-size="11" fill="#164e63">• Yalın: Vatan (ek yok)</text>\n  <text x="262" y="126" text-anchor="middle" font-size="11" fill="#164e63">• Belirtme (-ı/-i): Vatan-ı</text>\n  <text x="262" y="148" text-anchor="middle" font-size="11" fill="#164e63">• Yönelme (-e/-a): Vatan-a</text>\n  <text x="262" y="170" text-anchor="middle" font-size="11" fill="#164e63">• Bulunma (-de): Vatan-da</text>\n  <text x="262" y="192" text-anchor="middle" font-size="11" fill="#164e63">• Ayrılma (-den): Vatan-dan</text>\n  <rect x="352" y="55" width="152" height="180" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="428" y="78" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">3. İyelik (Aitlik) Ekleri</text>\n  <text x="428" y="104" text-anchor="middle" font-size="11" fill="#581c87">• (Benim) bayrağ-ım</text>\n  <text x="428" y="126" text-anchor="middle" font-size="11" fill="#581c87">• (Senin) bayrağ-ın</text>\n  <text x="428" y="148" text-anchor="middle" font-size="11" fill="#581c87">• (Onun) bayrağ-ı</text>\n  <text x="428" y="170" text-anchor="middle" font-size="11" fill="#581c87">• (Bizim) bayrağ-ımız</text>\n  <text x="428" y="192" text-anchor="middle" font-size="11" fill="#581c87">• (Onların) bayrak-ları</text>\n  <rect x="518" y="55" width="162" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="599" y="78" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">4. Tamlayan &amp; Soru</text>\n  <text x="599" y="104" text-anchor="middle" font-size="11" fill="#831843">• İlgi (Tamlayan) Eki:</text>\n  <text x="599" y="122" text-anchor="middle" font-size="11" fill="#831843">-ın/-in/-un/-ün (nın/nin)</text>\n  <text x="599" y="140" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">«Millet-in bağımsızlığ-ı»</text>\n  <text x="599" y="168" text-anchor="middle" font-size="11" fill="#831843">• Soru Eki (mı/mi/mu/mü):</text>\n  <text x="599" y="186" text-anchor="middle" font-size="11" fill="#831843">Kelimeden ayrı yazılır!</text>\n  <text x="599" y="204" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">«Şiiri okudun mu?»</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BELİRTME HÂL EKİ (-ı/-i) İLE 3. TEKİL İYELİK EKİ (-ı/-i) AYRIMI</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">3. Tekil Kişi İyelik Eki (-ı/-i/-sı/-si)</text>\n  <text x="180" y="108" text-anchor="middle" font-size="11" fill="#7c2d12">• Kelimenin başına «ONUN» zamiri</text>\n  <text x="180" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#7c2d12">getirildiğinde cümle anlamlı olur.</text>\n  <text x="180" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">Örnek: «Evi çok temiz ve düzenliydi.»</text>\n  <text x="180" y="178" text-anchor="middle" font-size="11" fill="#334155">→ «Onun ev-i» (Aitlik bildirir = İyelik eki)</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#475569">İsim tamlamasında tamlanan görevindedir.</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Belirtme Hâl (Durum) Eki (-ı/-i/-u/-ü)</text>\n  <text x="520" y="108" text-anchor="middle" font-size="11" fill="#14532d">• Başına «ONUN» gelmez; fiile sorulan</text>\n  <text x="520" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">«Neyi? / Kimi?» sorusuna cevap verir.</text>\n  <text x="520" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Örnek: «Evi birlikte boyadılar.»</text>\n  <text x="520" y="178" text-anchor="middle" font-size="11" fill="#334155">→ (Neyi boyadılar? Ev-i = Belirtme hâl eki)</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" fill="#475569">«Evi-n-i boyadı» → İlk -i iyelik, ikinci -i hâl ekidir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
